def guidance(key):
    return GUIDANCE[key][int(is_spanish())]


def analysis_context(key):
    title, purpose, method, limitation = guidance(key)
    st.caption(f"{tr('Why this matters')}: {purpose}")
    with st.popover(title, icon=":material/info:"):
        st.markdown(f"**{tr('Purpose')}**\n\n{purpose}")
        st.markdown(f"**{tr('Method')}**\n\n{method}")
        st.markdown(f"**{tr('Interpretation and limits')}**\n\n{limitation}")


def analyses_overview():
    with st.popover(tr("Why these analyses matter"), icon=":material/info:"):
        st.dataframe(pd.DataFrame([{tr("Analysis"): guidance(key)[0], tr("Purpose"): guidance(key)[1]}
                                   for key in GUIDANCE]), hide_index=True, width="stretch")
        st.caption(tr("These analyses support comparisons within the simulation; they do not establish measured performance at operating datacenters."))
